q('gramer','هَذِهِ هِيَ الْقِصَّةُ ---- حَدَّثْتُكَ عَنْهَا أَمْسِ.',['الَّذِي','الَّتِي','الَّذِينَ','اللَّتَانِ','اللَّائِي'],1,'Müennes müfred: الَّتِي; âid zamir عَنْهَا.')
