for metin,s,d,a in [
 ('لَمْ يَعُدِ الْعَمَلُ مِنَ الْمَنْزِلِ اسْتِثْنَاءً، بَلْ أَصْبَحَ خِيَارًا يُفَضِّلُهُ كَثِيرٌ مِنَ الْمُوَظَّفِينَ.',['Evden çalışma artık bir istisna olmaktan çıktı; aksine birçok çalışanın tercih ettiği bir seçenek hâline geldi.','Evden çalışma hiçbir zaman bir istisna olmadı; ama birçok çalışan onu tercih etti.','Çalışanların çoğu evden çalışmayı bir istisna olarak görmeye başladı.','Evden çalışma istisnai bir durumdur ve çalışanlar onu tercih etmez.','Birçok çalışan, evden çalışmanın bir seçenek olarak kalmasını istemiyor.'],0,'لم يعد = artık … değil; بل أصبح = aksine … oldu.'),
 ('يَرَى الْبَاحِثُونَ أَنَّ تَغَيُّرَ الْمُنَاخِ سَيُؤَثِّرُ تَأْثِيرًا بَالِغًا فِي إِنْتَاجِ الْغِذَاءِ خِلَالَ الْعُقُودِ الْقَادِمَةِ.',['Araştırmacılar, iklim değişikliğinin geçen on yıllarda gıda üretimini derinden etkilediğini düşünüyor.','Araştırmacılar, iklim değişikliğinin önümüzdeki on yıllarda gıda üretimini derinden etkileyeceği görüşünde.','Araştırmacılara göre gıda üretimi iklimi önümüzdeki yıllarda değiştirecek.','Araştırmacılar, gıda üretiminin iklim değişikliğinden etkilenmeyeceğini düşünüyor.','Araştırmacılar önümüzdeki on yılda iklim değişikliğini incelemeye karar verdi.'],1,'سيؤثر: gelecek; العقود القادمة: önümüzdeki on yıllar.'),
 ('مَا كَانَ لِلْمَشْرُوعِ أَنْ يَنْجَحَ لَوْلَا تَعَاوُنُ الْفَرِيقِ بِأَكْمَلِهِ.',['Proje, ekibin tamamı iş birliği yaptığı için başarısız oldu.','Ekibin bir kısmı iş birliği yapsaydı proje başarılı olurdu.','Ekibin tamamının iş birliği olmasaydı proje başarılı olamazdı.','Proje başarılı oldu ama ekip iş birliği yapmadı.','Ekip, projenin başarılı olması için iş birliği yapmak istemedi.'],2,'ما كان لـ… أن: olacak şey değildi; لولا: olmasaydı.'),
 ('Müzeyi ziyaret edenlerin sayısı geçen yıla göre iki katına çıktı.',['تَضَاعَفَ عَدَدُ زُوَّارِ الْمَتْحَفِ مُقَارَنَةً بِالْعَامِ الْمَاضِي.','زَارَ الْمَتْحَفَ عَدَدٌ قَلِيلٌ فِي الْعَامِ الْمَاضِي.','سَيَتَضَاعَفُ عَدَدُ الزُّوَّارِ فِي الْعَامِ الْقَادِمِ.','انْخَفَضَ عَدَدُ زُوَّارِ الْمَتْحَفِ إِلَى النِّصْفِ.','افْتُتِحَ الْمَتْحَفُ فِي الْعَامِ الْمَاضِي لِلزُّوَّارِ.'],0,'تضاعف: iki katına çıktı; مقارنة بـ: …e göre.'),
 ('Öğrencilerin çoğu sınavın beklediklerinden daha kolay olduğunu söyledi.',['قَالَ مُعْظَمُ الطُّلَّابِ إِنَّ الِامْتِحَانَ كَانَ أَسْهَلَ مِمَّا تَوَقَّعُوا.','تَوَقَّعَ الطُّلَّابُ أَنْ يَكُونَ الِامْتِحَانُ صَعْبًا جِدًّا.','قَالَ بَعْضُ الطُّلَّابِ إِنَّ الِامْتِحَانَ كَانَ صَعْبًا.','لَمْ يَتَوَقَّعِ الطُّلَّابُ أَنْ يَنْجَحُوا فِي الِامْتِحَانِ.','سَيَكُونُ الِامْتِحَانُ أَسْهَلَ مِنَ الْمُتَوَقَّعِ.'],0,'معظم: çoğu; أسهل مما توقعوا: bekledikleri­nden daha kolay. Kavlden sonra إنّ kesreli.'),
 ('Eğer erken yola çıksaydık treni kaçırmazdık.',['لَوْ خَرَجْنَا مُبَكِّرًا لَمَا فَاتَنَا الْقِطَارُ.','إِذَا خَرَجْنَا مُبَكِّرًا سَنَلْحَقُ الْقِطَارَ.','خَرَجْنَا مُبَكِّرًا فَلَحِقْنَا الْقِطَارَ.','فَاتَنَا الْقِطَارُ لِأَنَّنَا خَرَجْنَا مُبَكِّرًا.','لَمْ نَخْرُجْ مُبَكِّرًا وَلَكِنَّنَا لَحِقْنَا الْقِطَارَ.'],0,'Gerçekleşmemiş şart: لو … لما.')]:
    q('ceviri',metin,s,d,a)
# 43-62 PARAGRAF (5x4)
pars = {
'p1':('بَنَى الْمِعْمَارُ سِنَانٌ جَامِعَ السُّلَيْمَانِيَّةِ فِي إِسْطَنْبُولَ بِأَمْرٍ مِنَ السُّلْطَانِ سُلَيْمَانَ الْقَانُونِيِّ، وَاسْتَغْرَقَ بِنَاؤُهُ نَحْوَ سَبْعِ سَنَوَاتٍ. وَلَا يَقْتَصِرُ الْجَامِعُ عَلَى مَكَانٍ لِلصَّلَاةِ، بَلْ هُوَ مُجَمَّعٌ يَضُمُّ مَدَارِسَ وَمُسْتَشْفًى وَمَطْبَخًا لِإِطْعَامِ الْفُقَرَاءِ وَمَكْتَبَةً. وَيُعْرَفُ سِنَانٌ بِحِرْصِهِ عَلَى الْمَتَانَةِ، فَقَدْ صَمَدَتْ مَبَانِيهِ أَمَامَ زَلَازِلَ عَدِيدَةٍ. وَيَرَى الْمُؤَرِّخُونَ أَنَّ هَذَا الْجَامِعَ يَعْكِسُ رُؤْيَةَ الدَّوْلَةِ الْعُثْمَانِيَّةِ الَّتِي جَمَعَتْ بَيْنَ الْعِبَادَةِ وَخِدْمَةِ الْمُجْتَمَعِ.',[
  ('مَا الْفِكْرَةُ الرَّئِيسَةُ لِلنَّصِّ؟',['جَامِعُ السُّلَيْمَانِيَّةِ مُجَمَّعٌ يَجْمَعُ الْعِبَادَةَ وَخِدْمَةَ الْمُجْتَمَعِ','حَيَاةُ السُّلْطَانِ سُلَيْمَانَ الْقَانُونِيِّ','الزَّلَازِلُ فِي إِسْطَنْبُولَ','طُرُقُ إِطْعَامِ الْفُقَرَاءِ','تَارِيخُ الْمَكْتَبَاتِ الْعُثْمَانِيَّةِ'],0,'Metnin özü: cami, ibadet ve hizmeti birleştiren bir külliyedir.'),
  ('كَمِ اسْتَغْرَقَ بِنَاءُ الْجَامِعِ تَقْرِيبًا؟',['سَنَةً وَاحِدَةً','ثَلَاثَ سَنَوَاتٍ','سَبْعَ سَنَوَاتٍ','عَشْرَ سَنَوَاتٍ','عِشْرِينَ سَنَةً'],2,'استغرق بناؤه نحو سبع سنوات.'),
  ('أَيُّ مِمَّا يَلِي لَمْ يُذْكَرْ ضِمْنَ مُكَوِّنَاتِ الْمُجَمَّعِ؟',['الْمَدَارِسُ','الْمُسْتَشْفَى','الْمَطْبَخُ','الْحَمَّامُ','الْمَكْتَبَةُ'],3,'Hamam metinde geçmez.'),
  ('يُفْهَمُ مِنَ النَّصِّ أَنَّ مَبَانِيَ سِنَانٍ ----.',['تَهَدَّمَتْ فِي أَوَّلِ زِلْزَالٍ','بُنِيَتْ بِسُرْعَةٍ كَبِيرَةٍ','قَاوَمَتِ الزَّلَازِلَ بِفَضْلِ مَتَانَتِهَا','لَمْ تَكُنْ تَهْتَمُّ بِالْفُقَرَاءِ','كَانَتْ خَارِجَ إِسْطَنْبُولَ فَقَطْ'],2,'صمدت مبانيه أمام زلازل عديدة.')]),
'p2':('تُعَدُّ الْقَهْوَةُ مِنْ أَكْثَرِ الْمَشْرُوبَاتِ انْتِشَارًا فِي الْعَالَمِ. وَتُشِيرُ الرِّوَايَاتُ إِلَى أَنَّ أَصْلَهَا يَعُودُ إِلَى الْحَبَشَةِ، ثُمَّ انْتَقَلَتْ إِلَى الْيَمَنِ حَيْثُ زُرِعَتْ عَلَى نِطَاقٍ وَاسِعٍ فِي الْقَرْنِ الْخَامِسَ عَشَرَ. وَمِنْ مِينَاءِ الْمُخَا الْيَمَنِيِّ انْطَلَقَتْ تِجَارَتُهَا إِلَى مَكَّةَ وَالْقَاهِرَةِ وَإِسْطَنْبُولَ، ثُمَّ إِلَى أُورُوبَّا. وَقَدْ أَثَارَتْ فِي بِدَايَاتِهَا جَدَلًا بَيْنَ الْفُقَهَاءِ حَوْلَ حُكْمِ شُرْبِهَا، قَبْلَ أَنْ تُصْبِحَ جُزْءًا مِنَ الْحَيَاةِ الْيَوْمِيَّةِ وَتَظْهَرَ الْمَقَاهِي بِوَصْفِهَا أَمَاكِنَ لِلِقَاءِ وَالْحِوَارِ.',[
  ('حَسَبَ النَّصِّ، أَيْنَ زُرِعَتِ الْقَهْوَةُ عَلَى نِطَاقٍ وَاسِعٍ؟',['فِي الْحَبَشَةِ','فِي الْيَمَنِ','فِي مِصْرَ','فِي أُورُوبَّا','فِي مَكَّةَ'],1,'انتقلت إلى اليمن حيث زرعت على نطاق واسع.'),
  ('مَا الدَّوْرُ الَّذِي أَدَّاهُ مِينَاءُ الْمُخَا؟',['كَانَ أَوَّلَ مَقْهًى فِي الْعَالَمِ','كَانَ مَرْكَزًا لِتِجَارَةِ الْقَهْوَةِ إِلَى الْبُلْدَانِ الْأُخْرَى','مَنَعَ تَصْدِيرَ الْقَهْوَةِ','كَانَ مَكَانًا لِجَدَلِ الْفُقَهَاءِ','زُرِعَتْ فِيهِ الْقَهْوَةُ أَوَّلَ مَرَّةٍ'],1,'ومن ميناء المخا انطلقت تجارتها.'),
  ('يُفْهَمُ مِنَ النَّصِّ أَنَّ الْقَهْوَةَ ----.',['قُبِلَتْ دُونَ أَيِّ نِقَاشٍ','كَانَتْ مَوْضِعَ جَدَلٍ فِقْهِيٍّ فِي بِدَايَتِهَا','لَمْ تَصِلْ إِلَى أُورُوبَّا','ظَهَرَتْ أَوَّلًا فِي إِسْطَنْبُولَ','مُنِعَتْ فِي الْيَمَنِ'],1,'أثارت في بداياتها جدلًا بين الفقهاء.'),
  ('مَا الْعُنْوَانُ الْأَنْسَبُ لِلنَّصِّ؟',['رِحْلَةُ الْقَهْوَةِ مِنَ الْحَبَشَةِ إِلَى الْعَالَمِ','أَضْرَارُ الْقَهْوَةِ عَلَى الصِّحَّةِ','تَارِيخُ الْيَمَنِ السِّيَاسِيُّ','الْفُقَهَاءُ وَالتِّجَارَةُ','الْمَقَاهِي الْحَدِيثَةُ'],0,'Metin kahvenin yolculuğunu anlatıyor.')]),
'p3':('يَعْتَمِدُ كَثِيرٌ مِنَ الطُّلَّابِ عَلَى إِعَادَةِ قِرَاءَةِ الدَّرْسِ مَرَّاتٍ عَدِيدَةٍ قَبْلَ الِامْتِحَانِ، ظَنًّا مِنْهُمْ أَنَّ ذَلِكَ يُرَسِّخُ الْمَعْلُومَاتِ. غَيْرَ أَنَّ أَبْحَاثَ عِلْمِ النَّفْسِ التَّرْبَوِيِّ تُبَيِّنُ أَنَّ أَنْجَعَ الطُّرُقِ هِيَ اسْتِرْجَاعُ الْمَعْلُومَاتِ مِنَ الذَّاكِرَةِ، كَأَنْ يَخْتَبِرَ الطَّالِبُ نَفْسَهُ بِأَسْئِلَةٍ، مَعَ تَوْزِيعِ الْمُرَاجَعَةِ عَلَى فَتَرَاتٍ مُتَبَاعِدَةٍ. فَالْمَعْلُومَةُ الَّتِي نُجْهِدُ أَنْفُسَنَا فِي تَذَكُّرِهَا تَبْقَى أَطْوَلَ مِنَ الَّتِي نَقْرَؤُهَا وَنَحْنُ مُرْتَاحُونَ.',[
  ('مَا الْخَطَأُ الشَّائِعُ الَّذِي يُشِيرُ إِلَيْهِ النَّصُّ؟',['الِاعْتِمَادُ عَلَى إِعَادَةِ الْقِرَاءَةِ وَحْدَهَا','الدِّرَاسَةُ فِي الْمَكْتَبَةِ','النَّوْمُ قَبْلَ الِامْتِحَانِ','الْعَمَلُ فِي مَجْمُوعَاتٍ','حَلُّ الْأَسْئِلَةِ'],0,'يعتمد كثير… على إعادة قراءة الدرس… ظنًّا منهم.'),
  ('حَسَبَ النَّصِّ، مَا أَنْجَعُ طُرُقِ التَّعَلُّمِ؟',['قِرَاءَةُ الدَّرْسِ بِصَوْتٍ عَالٍ','اسْتِرْجَاعُ الْمَعْلُومَاتِ وَتَوْزِيعُ الْمُرَاجَعَةِ عَلَى فَتَرَاتٍ','حِفْظُ الدَّرْسِ لَيْلَةَ الِامْتِحَانِ','تَلْخِيصُ الْكِتَابِ','الِاسْتِمَاعُ إِلَى الْمُعَلِّمِ فَقَطْ'],1,'الاسترجاع… مع توزيع المراجعة.'),
  ('كَلِمَةُ «أَنْجَعَ» فِي النَّصِّ أَقْرَبُ مَعْنًى إِلَى ----.',['أَسْهَلَ','أَقْدَمَ','أَكْثَرَ فَاعِلِيَّةً','أَطْوَلَ','أَكْثَرَ شُيُوعًا'],2,'أنجع: en etkili.'),
  ('يُسْتَنْتَجُ مِنَ النَّصِّ أَنَّ الْجُهْدَ فِي التَّذَكُّرِ ----.',['يُضْعِفُ الذَّاكِرَةَ','لَا فَائِدَةَ مِنْهُ','يُسَاعِدُ عَلَى بَقَاءِ الْمَعْلُومَةِ مُدَّةً أَطْوَلَ','يُسَبِّبُ الْقَلَقَ','يُنَاسِبُ الصِّغَارَ فَقَطْ'],2,'المعلومة التي نجهد أنفسنا في تذكرها تبقى أطول.')]),
'p4':('تَقَعُ مَدِينَةُ فَاسَ فِي شَمَالِ الْمَغْرِبِ، وَقَدْ أَسَّسَهَا إِدْرِيسُ الثَّانِي فِي أَوَاخِرِ الْقَرْنِ الثَّامِنِ الْمِيلَادِيِّ. وَتَضُمُّ الْمَدِينَةُ جَامِعَ الْقَرَوِيِّينَ الَّذِي أَسَّسَتْهُ فَاطِمَةُ الْفِهْرِيَّةُ، وَيُعَدُّ مِنْ أَقْدَمِ الْمُؤَسَّسَاتِ التَّعْلِيمِيَّةِ الَّتِي مَا زَالَتْ قَائِمَةً. وَتَشْتَهِرُ فَاسُ الْقَدِيمَةُ بِأَزِقَّتِهَا الضَّيِّقَةِ الَّتِي لَا تَدْخُلُهَا السَّيَّارَاتُ، وَبِدَبَّاغَاتِهَا التَّقْلِيدِيَّةِ الَّتِي تُصْبَغُ فِيهَا الْجُلُودُ بِأَلْوَانٍ زَاهِيَةٍ. وَقَدْ أُدْرِجَتِ الْمَدِينَةُ الْقَدِيمَةُ فِي قَائِمَةِ التُّرَاثِ الْعَالَمِيِّ.',[
  ('مَنْ أَسَّسَ جَامِعَ الْقَرَوِيِّينَ؟',['إِدْرِيسُ الثَّانِي','فَاطِمَةُ الْفِهْرِيَّةُ','إِدْرِيسُ الْأَوَّلُ','سُلْطَانُ الْمَغْرِبِ','عُلَمَاءُ فَاسَ'],1,'الذي أسسته فاطمة الفهرية.'),
  ('بِمَ تَشْتَهِرُ فَاسُ الْقَدِيمَةُ؟',['بِشَوَارِعِهَا الْوَاسِعَةِ','بِمَصَانِعِ السَّيَّارَاتِ','بِأَزِقَّتِهَا الضَّيِّقَةِ وَدَبَّاغَاتِهَا','بِشَوَاطِئِهَا','بِنَاطِحَاتِ السَّحَابِ'],2,'أزقتها الضيقة ودباغاتها.'),
  ('مَتَى أُسِّسَتْ مَدِينَةُ فَاسَ؟',['فِي الْقَرْنِ الْخَامِسِ','فِي أَوَاخِرِ الْقَرْنِ الثَّامِنِ الْمِيلَادِيِّ','فِي الْقَرْنِ الْعِشْرِينَ','فِي الْقَرْنِ الثَّالِثَ عَشَرَ','قَبْلَ الْمِيلَادِ'],1,'في أواخر القرن الثامن الميلادي.'),
  ('أَيُّ عِبَارَةٍ صَحِيحَةٌ وَفْقَ النَّصِّ؟',['جَامِعُ الْقَرَوِيِّينَ لَمْ يَعُدْ قَائِمًا','تَدْخُلُ السَّيَّارَاتُ جَمِيعَ أَزِقَّةِ الْمَدِينَةِ','أُدْرِجَتِ الْمَدِينَةُ الْقَدِيمَةُ فِي قَائِمَةِ التُّرَاثِ الْعَالَمِيِّ','تَقَعُ فَاسُ فِي جَنُوبِ الْمَغْرِبِ','تُصْبَغُ الْجُلُودُ بِلَوْنٍ وَاحِدٍ'],2,'وقد أدرجت المدينة القديمة في قائمة التراث العالمي.')]),
'p5':('يَلْجَأُ كَثِيرٌ مِنَ الْمُدُنِ الْكُبْرَى الْيَوْمَ إِلَى زِرَاعَةِ الْأَشْجَارِ عَلَى أَسْطُحِ الْمَبَانِي وَفِي الشَّوَارِعِ لِمُوَاجَهَةِ ظَاهِرَةِ «الْجُزُرِ الْحَرَارِيَّةِ»، إِذْ تَمْتَصُّ الْخَرَسَانَةُ وَالْإِسْفَلْتُ حَرَارَةَ الشَّمْسِ نَهَارًا وَتُطْلِقُهَا لَيْلًا، فَتَرْتَفِعُ دَرَجَةُ حَرَارَةِ الْمَدِينَةِ عَنِ الْمَنَاطِقِ الرِّيفِيَّةِ الْمُجَاوِرَةِ. وَتُسْهِمُ الْأَشْجَارُ فِي تَلْطِيفِ الْجَوِّ بِظِلَالِهَا وَبِمَا تُطْلِقُهُ مِنْ بُخَارِ الْمَاءِ، فَضْلًا عَنْ تَحْسِينِ جَوْدَةِ الْهَوَاءِ وَتَقْلِيلِ اسْتِهْلَاكِ الطَّاقَةِ فِي التَّبْرِيدِ.',[
  ('مَا سَبَبُ ظَاهِرَةِ «الْجُزُرِ الْحَرَارِيَّةِ» حَسَبَ النَّصِّ؟',['قِلَّةُ الْأَمْطَارِ','امْتِصَاصُ الْخَرَسَانَةِ وَالْإِسْفَلْتِ لِلْحَرَارَةِ ثُمَّ إِطْلَاقُهَا','كَثْرَةُ الْأَشْجَارِ','قُرْبُ الْمُدُنِ مِنَ الْبَحْرِ','ارْتِفَاعُ الْمَبَانِي فَقَطْ'],1,'إذ تمتص الخرسانة والإسفلت حرارة الشمس… وتطلقها ليلًا.'),
  ('أَيٌّ مِمَّا يَلِي لَيْسَ مِنْ فَوَائِدِ الْأَشْجَارِ الْمَذْكُورَةِ؟',['الظِّلُّ','إِطْلَاقُ بُخَارِ الْمَاءِ','تَحْسِينُ جَوْدَةِ الْهَوَاءِ','تَقْلِيلُ اسْتِهْلَاكِ الطَّاقَةِ','زِيَادَةُ عَدَدِ السُّكَّانِ'],4,'Nüfus artışı metinde geçmez.'),
  ('تُشِيرُ عِبَارَةُ «فَضْلًا عَنْ» فِي النَّصِّ إِلَى ----.',['الْإِضَافَةِ','الِاسْتِثْنَاءِ','السَّبَبِ','النَّتِيجَةِ','الشَّرْطِ'],0,'فضلًا عن: …nın yanı sıra (ekleme).'),
  ('الْغَرَضُ الرَّئِيسُ مِنَ النَّصِّ هُوَ ----.',['شَرْحُ دَوْرِ الْأَشْجَارِ فِي خَفْضِ حَرَارَةِ الْمُدُنِ','انْتِقَادُ الْمُدُنِ الرِّيفِيَّةِ','الدَّعْوَةُ إِلَى الْهِجْرَةِ إِلَى الرِّيفِ','وَصْفُ صِنَاعَةِ الْإِسْفَلْتِ','بَيَانُ أَنْوَاعِ الْأَشْجَارِ'],0,'Ağaçların şehir ısısını düşürmedeki rolü.')])}
for pid,(metin,sorular) in pars.items():
    P[pid]=metin
    for s,k,d,a in sorular: q('paragraf',s,k,d,a,pid)
# 63-67 DİYALOG
for metin,s,d,a in [
 ('سَعِيدٌ: هَلْ أَنْهَيْتَ كِتَابَةَ الْبَحْثِ؟\nخَالِدٌ: ----\nسَعِيدٌ: لَا بَأْسَ، مَا زَالَ أَمَامَكَ أُسْبُوعٌ كَامِلٌ.',['لَيْسَ بَعْدُ، بَقِيَ عَلَيَّ الْفَصْلُ الْأَخِيرُ.','نَعَمْ، وَسَلَّمْتُهُ أَمْسِ.','لَا أَعْرِفُ مَوْضُوعَ الْبَحْثِ.','أُحِبُّ الْكُتُبَ الْقَدِيمَةَ.','الْبَحْثُ عَنِ التَّارِيخِ.'],0,'“Sorun değil, hâlâ bir haftan var” cevabı bitmediğini gösterir.'),
 ('الْمُوَظَّفُ: كَيْفَ أَسْتَطِيعُ مُسَاعَدَتَكَ؟\nالزَّبُونُ: ----\nالْمُوَظَّفُ: تَفَضَّلْ، امْلَأْ هَذِهِ الِاسْتِمَارَةَ وَأَحْضِرْ صُورَةً شَخْصِيَّةً.',['أُرِيدُ أَنْ أَفْتَحَ حِسَابًا مَصْرِفِيًّا.','شُكْرًا، لَا أَحْتَاجُ شَيْئًا.','أَيْنَ أَقْرَبُ مَطْعَمٍ؟','كَمِ السَّاعَةُ الْآنَ؟','لَقَدْ أَغْلَقْتُ حِسَابِي.'],0,'Form ve fotoğraf istenmesi hesap açmaya işaret eder.'),
 ('الْأُمُّ: لِمَاذَا تَأَخَّرْتَ عَنِ الْمَدْرَسَةِ الْيَوْمَ؟\nالِابْنُ: ----\nالْأُمُّ: كَانَ عَلَيْكَ أَنْ تَخْرُجَ مُبَكِّرًا إِذَنْ.',['لِأَنَّ الْحَافِلَةَ تَأَخَّرَتْ بِسَبَبِ الزِّحَامِ.','لِأَنِّي وَصَلْتُ قَبْلَ الْجَمِيعِ.','لَمْ أَتَأَخَّرْ أَبَدًا.','الْمُعَلِّمُ غَائِبٌ الْيَوْمَ.','سَأَذْهَبُ غَدًا.'],0,'Anne “erken çıkmalıydın” der: gecikme sebebi trafik.'),
 ('سَلْمَى: مَا رَأْيُكِ أَنْ نَزُورَ الْمَعْرِضَ مَسَاءَ الْيَوْمِ؟\nهُدَى: ----\nسَلْمَى: إِذَنْ نُؤَجِّلُ الزِّيَارَةَ إِلَى نِهَايَةِ الْأُسْبُوعِ.',['أَعْتَذِرُ، عِنْدِي امْتِحَانٌ غَدًا صَبَاحًا.','فِكْرَةٌ رَائِعَةٌ، لِنَذْهَبْ الْآنَ.','زُرْتُهُ أَمْسِ مَعَكِ.','الْمَعْرِضُ فِي وَسَطِ الْمَدِينَةِ.','أُحِبُّ الرَّسْمَ كَثِيرًا.'],0,'Ertelenmesi, Hüdâ’nın bugün müsait olmadığını gösterir.'),
 ('الْمَرِيضُ: هَلْ يَجِبُ أَنْ أَتَنَاوَلَ الدَّوَاءَ قَبْلَ الْأَكْلِ؟\nالطَّبِيبُ: ----\nالْمَرِيضُ: حَسَنًا، سَأَلْتَزِمُ بِذَلِكَ.',['لَا، تَنَاوَلْهُ بَعْدَ الْأَكْلِ مَرَّتَيْنِ يَوْمِيًّا.','الدَّوَاءُ غَالِي الثَّمَنِ.','لَا أَعْرِفُ هَذَا الدَّوَاءَ.','أَيْنَ تَسْكُنُ؟','لَقَدْ شُفِيتَ تَمَامًا.'],0,'Hasta talimata uyacağını söylüyor: doktor bir talimat vermiş olmalı.')]:
    q('diyalog',metin,s,d,a)
# 68-71 YAKIN ANLAM
for metin,s,d,a in [
 ('لَا يَكَادُ يَمُرُّ يَوْمٌ دُونَ أَنْ يَزُورَ جَدَّهُ.',['يَزُورُ جَدَّهُ كُلَّ يَوْمٍ تَقْرِيبًا.','نَادِرًا مَا يَزُورُ جَدَّهُ.','لَمْ يَزُرْ جَدَّهُ مُنْذُ أَيَّامٍ.','يَزُورُ جَدَّهُ مَرَّةً فِي الْأُسْبُوعِ.','زَارَهُ جَدُّهُ أَمْسِ.'],0,'Neredeyse her gün ziyaret eder.'),
 ('مَا كَانَ أَحَدٌ يَتَوَقَّعُ أَنْ يَفُوزَ الْفَرِيقُ الصَّغِيرُ.',['فَازَ الْفَرِيقُ الصَّغِيرُ كَمَا تَوَقَّعَ الْجَمِيعُ.','كَانَ فَوْزُ الْفَرِيقِ الصَّغِيرِ غَيْرَ مُتَوَقَّعٍ.','لَمْ يَشْتَرِكِ الْفَرِيقُ الصَّغِيرُ.','خَسِرَ الْفَرِيقُ الصَّغِيرُ.','تَوَقَّعَ بَعْضُهُمْ فَوْزَهُ.'],1,'Kimse beklemiyordu = beklenmedik.'),
 ('لَيْسَ هُنَاكَ مَا يَمْنَعُ مِنْ تَأْجِيلِ الِاجْتِمَاعِ.',['يُمْكِنُ تَأْجِيلُ الِاجْتِمَاعِ.','لَا يَجُوزُ تَأْجِيلُ الِاجْتِمَاعِ.','أُلْغِيَ الِاجْتِمَاعُ.','الِاجْتِمَاعُ فِي مَوْعِدِهِ حَتْمًا.','تَأَخَّرَ الِاجْتِمَاعُ أَمْسِ.'],0,'Engel yok = mümkün.'),
 ('سُرْعَانَ مَا نَدِمَ عَلَى قَرَارِهِ.',['نَدِمَ عَلَى قَرَارِهِ بَعْدَ سَنَوَاتٍ.','لَمْ يَنْدَمْ عَلَى قَرَارِهِ.','نَدِمَ عَلَى قَرَارِهِ بَعْدَ وَقْتٍ قَصِيرٍ.','اتَّخَذَ قَرَارَهُ بِسُرْعَةٍ.','فَكَّرَ طَوِيلًا قَبْلَ قَرَارِهِ.'],2,'سرعان ما: kısa sürede.')]:
    q('yakin',metin,s,d,a)
# 72-75 BOŞLUĞA UYGUN CÜMLE
for pid,metin,s,d,a in [
 ('b1','تَعَلُّمُ لُغَةٍ جَدِيدَةٍ لَا يَقْتَصِرُ عَلَى حِفْظِ الْكَلِمَاتِ وَالْقَوَاعِدِ. ---- فَاللُّغَةُ تَحْمِلُ طَرِيقَةَ أَهْلِهَا فِي التَّفْكِيرِ وَالتَّعْبِيرِ.',['بَلْ هُوَ أَيْضًا اقْتِرَابٌ مِنْ ثَقَافَةِ أَهْلِهَا.','وَلِذَلِكَ يَكْفِي حِفْظُ الْكَلِمَاتِ.','وَالْقَوَاعِدُ صَعْبَةٌ جِدًّا.','لِأَنَّ الْكُتُبَ قَلِيلَةٌ.','وَكَثِيرٌ مِنَ النَّاسِ لَا يُسَافِرُونَ.'],0,'Sonraki cümle “dil, düşünme biçimini taşır” diyor: kültüre yaklaşma.'),
 ('b2','ارْتَفَعَ عَدَدُ السُّيَّاحِ الَّذِينَ زَارُوا الْمَدِينَةَ هَذَا الْعَامَ ارْتِفَاعًا مَلْحُوظًا. ---- وَقَدْ دَفَعَ ذَلِكَ الْفَنَادِقَ إِلَى زِيَادَةِ عَدَدِ غُرَفِهَا.',['وَيَعُودُ ذَلِكَ إِلَى افْتِتَاحِ الْمَطَارِ الْجَدِيدِ وَتَحْسِينِ الطُّرُقِ.','وَلَكِنَّ الْفَنَادِقَ أُغْلِقَتْ.','وَيُفَضِّلُ السُّيَّاحُ الْبَقَاءَ فِي بُيُوتِهِمْ.','وَالطَّقْسُ بَارِدٌ فِي الشِّتَاءِ.','وَقَلَّ عَدَدُ الزُّوَّارِ كَثِيرًا.'],0,'Artışın sebebi verilip ardından sonucu (otellerin oda artırması) gelir.'),
 ('b3','يَقْضِي الْأَطْفَالُ الْيَوْمَ سَاعَاتٍ طَوِيلَةً أَمَامَ الشَّاشَاتِ. ---- لِذَلِكَ يَنْصَحُ الْخُبَرَاءُ بِتَحْدِيدِ وَقْتٍ يَوْمِيٍّ لِاسْتِخْدَامِهَا.',['وَقَدْ يُؤَثِّرُ ذَلِكَ سَلْبًا فِي نَوْمِهِمْ وَتَرْكِيزِهِمْ.','وَهُمْ يُحِبُّونَ اللَّعِبَ فِي الْحَدَائِقِ.','وَالشَّاشَاتُ رَخِيصَةُ الثَّمَنِ.','وَيَذْهَبُونَ إِلَى الْمَدْرَسَةِ صَبَاحًا.','فَلَا ضَرَرَ فِي ذَلِكَ.'],0,'“Bu yüzden” öncesinde bir zarar belirtilmeli.'),
 ('b4','كَانَتْ بَغْدَادُ فِي الْعَصْرِ الْعَبَّاسِيِّ مَرْكَزًا عِلْمِيًّا عَالَمِيًّا. ---- وَمِنْهَا انْتَقَلَتْ كَثِيرٌ مِنَ الْمَعَارِفِ إِلَى الْأَنْدَلُسِ وَأُورُوبَّا.',['فَقَدْ تُرْجِمَتْ فِيهَا كُتُبُ الْيُونَانِ وَالْفُرْسِ وَالْهِنْدِ فِي بَيْتِ الْحِكْمَةِ.','وَلَمْ يَكُنْ فِيهَا أَيُّ مَكْتَبَةٍ.','وَهِيَ الْيَوْمَ عَاصِمَةُ الْعِرَاقِ.','وَيَمُرُّ فِيهَا نَهْرُ النِّيلِ.','وَقَدْ أَسَّسَهَا الْأُمَوِيُّونَ.'],0,'Bilim merkezi olmasını açıklayan cümle: Beytü’l-Hikme tercümeleri.')]:
    P[pid]=metin; q('bosluk','Parçada boş bırakılan yere hangi cümle gelmelidir?',s,d,a,pid)
# 76-80 ANLAM BÜTÜNLÜĞÜNÜ BOZAN
for pid,metin,d,a in [
 ('z1','(I) يُعَدُّ الْمَاءُ أَسَاسَ الْحَيَاةِ عَلَى الْأَرْضِ. (II) وَيُشَكِّلُ نَحْوَ سِتِّينَ فِي الْمِائَةِ مِنْ جِسْمِ الْإِنْسَانِ. (III) وَتَقَعُ أَكْبَرُ صَحْرَاءَ حَارَّةٍ فِي شَمَالِ أَفْرِيقِيَا. (IV) لِذَلِكَ يَنْصَحُ الْأَطِبَّاءُ بِشُرْبِ كَمِّيَّةٍ كَافِيَةٍ مِنْهُ يَوْمِيًّا. (V) فَنَقْصُهُ يُسَبِّبُ التَّعَبَ وَالصُّدَاعَ.',2,'III. cümle (Sahra) suyun vücuttaki önemi konusundan sapar.'),
 ('z2','(I) ظَهَرَتِ الطِّبَاعَةُ الْحَدِيثَةُ فِي أُورُوبَّا فِي الْقَرْنِ الْخَامِسَ عَشَرَ. (II) وَقَدْ أَدَّتْ إِلَى انْتِشَارِ الْكُتُبِ بِأَسْعَارٍ أَقَلَّ. (III) فَأَصْبَحَتِ الْمَعْرِفَةُ فِي مُتَنَاوَلِ عَدَدٍ أَكْبَرَ مِنَ النَّاسِ. (IV) وَتَشْتَهِرُ أُورُوبَّا بِجِبَالِهَا الْمُغَطَّاةِ بِالثُّلُوجِ. (V) وَيَرَى الْمُؤَرِّخُونَ أَنَّهَا مَهَّدَتْ لِحَرَكَةِ النَّهْضَةِ.',3,'IV. cümle (dağlar) matbaa konusuyla ilgisizdir.'),
 ('z3','(I) تُعَدُّ النَّحْلَةُ مِنْ أَنْفَعِ الْحَشَرَاتِ لِلْإِنْسَانِ. (II) فَهِيَ تُنْتِجُ الْعَسَلَ وَالشَّمْعَ. (III) كَمَا تُسْهِمُ فِي تَلْقِيحِ كَثِيرٍ مِنَ النَّبَاتَاتِ. (IV) وَيُحِبُّ الْأَطْفَالُ مُشَاهَدَةَ الرُّسُومِ الْمُتَحَرِّكَةِ. (V) وَلِذَلِكَ يُحَذِّرُ الْعُلَمَاءُ مِنْ تَرَاجُعِ أَعْدَادِهَا.',3,'IV. cümle konudan tamamen kopuktur.'),
 ('z4','(I) أَصْبَحَ الْهَاتِفُ الذَّكِيُّ جُزْءًا مِنْ حَيَاتِنَا الْيَوْمِيَّةِ. (II) فَنَسْتَخْدِمُهُ فِي التَّوَاصُلِ وَالتَّسَوُّقِ وَالتَّعَلُّمِ. (III) وَكَانَ الْبَرِيدُ يُنْقَلُ قَدِيمًا عَلَى ظُهُورِ الْخَيْلِ. (IV) غَيْرَ أَنَّ الْإِفْرَاطَ فِي اسْتِخْدَامِهِ قَدْ يَضُرُّ بِالصِّحَّةِ. (V) لِذَا يَنْبَغِي اسْتِعْمَالُهُ بِاعْتِدَالٍ.',2,'III. cümle (eski posta) akışı bozar; IV’teki “غير أنّ” II’ye bağlanır.'),
 ('z5','(I) تَتَمَيَّزُ الْخَطُّ الْعَرَبِيُّ بِتَنَوُّعِ أَنْوَاعِهِ. (II) وَمِنْ أَشْهَرِهَا النَّسْخُ وَالثُّلُثُ وَالدِّيوَانِيُّ. (III) وَقَدْ بَرَعَ الْخَطَّاطُونَ الْعُثْمَانِيُّونَ فِي تَطْوِيرِهِ. (IV) وَيُعَدُّ الْأُرْزُ غِذَاءً رَئِيسًا فِي آسِيَا. (V) وَمَا زَالَتْ مَدَارِسُ الْخَطِّ تُعَلِّمُ هَذَا الْفَنَّ حَتَّى الْيَوْمِ.',3,'IV. cümle (pirinç) hat sanatı konusundan sapar.')]:
    P[pid]=metin; q('bozan','Hangi cümle anlam bütünlüğünü bozar?',['I','II','III','IV','V'],d,a,pid)
